  "test": "import pytest
import pydantic

from langfuse.api.commons.types.boolean_score import BooleanScore

def test_boolean_score_accepts_valid_values():
    # Should construct without error for 0 and 1
    bs0 = BooleanScore(value=0, string_value="False")
    assert bs0.value == 0
    bs1 = BooleanScore(value=1, string_value="True")
    assert bs1.value == 1

def test_boolean_score_invalid_value_raises():
    with pytest.raises(pydantic.ValidationError):
        BooleanScore(value=0.5, string_value="True")
